class OfflineFirstNewsRepository(
    private val database: NewsDatabase,
    private val remote: NewsRemoteSource,
    private val syncScheduler: SyncScheduler,
    private val clock: Clock
) {
    fun articles(query: Query): Flow<PagingData<Article>> = pager(query).flow
    suspend fun bookmark(id: ArticleId, desired: Boolean) = database.withTransaction { persistIntent(id, desired) }.also { syncScheduler.enqueue() }
}

